 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let position = 0;
+  while (position < template.length) {
+    const open = template.indexOf("{{", position);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(position) });
+      break;
+    }
+    if (open > position) {
+      tokens.push({ kind: "text", text: template.slice(position, open) });
+    }
+    const raw = template.startsWith("{{{", open);
+    const opener = raw ? "{{{" : "{{";
+    const closer = raw ? "}}}" : "}}";
+    const close = template.indexOf(closer, open + opener.length);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+    const inner = template.slice(open + opener.length, close).trim();
+    tokens.push(parseTag(inner, raw));
+    position = close + closer.length;
+  }
+  return tokens;
 }
+
+function parseTag(inner: string, raw: boolean): Token {
+  if (raw) {
+    return { kind: "value", expr: inner, raw: true };
+  }
+  const ifMatch = /^#if(?:\s+(.*))?$/.exec(inner);
+  if (ifMatch) {
+    return { kind: "if", path: (ifMatch[1] ?? "").trim() };
+  }
+  if (inner === "else") {
+    return { kind: "else" };
+  }
+  if (inner === "/if") {
+    return { kind: "end" };
+  }
+  return { kind: "value", expr: inner, raw: false };
+}
